capture_scripts.hw7_static.gd:
extends "res://tools/capture_reval_city.gd"

func _v(plan: CityPlan, x: float, z: float, up: float) -> Vector3:
	return Vector3(x, plan.ground_height(Vector2(x, z)) + up, z)

func _shots(plan: CityPlan) -> Array[Dictionary]:
	var shots: Array[Dictionary] = []
	for s in super._shots(plan):
		if s.name in ["street_pikk", "street_lai", "st_mary_aerial", "st_mary_door"]:
			s.name = "hw7_" + s.name
			shots.append(s)
	shots.append({"name":"hw7_lower_aerial", "eye":_v(plan, -80, -290, 105), "look":_v(plan, 45, -250, 0), "fov":60.0})
	shots.append({"name":"hw7_mary_west", "eye":_v(plan,-384,24,1.7), "look":_v(plan,-355,21,7), "fov":65.0})
	shots.append({"name":"hw7_mary_south", "eye":_v(plan,-356,44,1.7), "look":_v(plan,-353,22,7), "fov":65.0})
	shots.append({"name":"hw7_mary_east", "eye":_v(plan,-309,20,1.7), "look":_v(plan,-331,21,7), "fov":65.0})
	return shots
